arguments.content:
* {
    border: none;
    border-radius: 0;
    outline: none;
    box-shadow: none;
}

window#waybar {
    background-color: rgba(0, 0, 0, 0.7);
    color: #ffffff;
    font-family: "Ubuntu", "Segoe UI", sans-serif;
    font-size: 14px;
}

hyprland/workspaces {
    padding-left: 12px;
    padding-right: 12px;
}

hyprland/workspaces button {
    background-color: transparent;
    color: #ffffff;
    padding: 0 8px;
    border-radius: 4px;
}

hyprland/workspaces button.active {
    background-color: rgba(100, 200, 255, 0.3);
}

hyprland/window {
    padding-left: 12px;
    padding-right: 12px;
    font-weight: bold;
}

clock {
    padding-left: 12px;
    padding-right: 12px;
}

battery {
    padding-left: 12px;
