messages.content:
{
    "layer": "top",
    "position": "bottom",
    "height": 28,
    "modules-left": ["hyprland/workspaces"],
    "modules-center": ["hyprland/window"],
    "modules-right": ["clock", "battery"],
    "hyprland/workspaces": {
        "format": "{number}",
        "on-click": "activate"
    },
    "hyprland/window": {
        "format": "{}",
        "max-length": 50,
        "separator": "",
        "truncates-after": 3
    },
    "clock": {
        "format": "{:%H:%M}",
        "tooltip-format": "<big>{:%Y %B}</big>\n<tt><small>%a, %d %b %Y %H:%M</small></tt>"
    },
    "battery": {
        "states": {
            "warning": 30,
            "critical": 15
        }
    }
}

